#include <stdio.h>

int main(void) {
    int x = 10, y = 20;

    const int *p1 = &x;         /* 指向常量的指针 */
    p1 = &y;                    /* 改指针 OK */
    printf("p1 -> %d\n", *p1);

    int *const p2 = &x;         /* 常量指针 */
    *p2 = 99;                   /* 改内容 OK */
    printf("x = %d\n", x);

    const int *const p3 = &y;   /* 两者都锁 */
    printf("p3 -> %d\n", *p3);

    printf("const 修饰的是它右边紧邻的部分，读声明从右往左\n");
    return 0;
}
